// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

export interface TurnaroundOut {
  service: "Lab" | "Imaging";
  date_from: string;
  date_to: string;
  /** The MSDS score of AAC 4 (lab) or 11 (imaging) */
  score: "FullyMet" | "PartiallyMet" | "NotMet" | "NoData";
  classes: TurnaroundClassOut[];
  by_item: TurnaroundGroupOut[];
  late: TurnaroundLateOut[];
}

export interface TurnaroundClassOut {
  turnaround_class: "Routine" | "Emergency";
  /** Results due in the period: released, or still open past their due time */
  total: number;
  on_time: number;
  pct: number | null;
  /** The MSDS standard: 95 routine, 100 emergency */
  target_pct: number;
  median_minutes: number | null;
  p90_minutes: number | null;
  /** Lab: from the order to the sample's receipt; imaging: from the order to the examination */
  median_wait_minutes: number | null;
  /** Imaging: examinations performed within their target */
  wait_pct: number | null;
}

export interface TurnaroundGroupOut {
  /** The test code, or the modality */
  item_key: string;
  item_name: string;
  turnaround_class: "Routine" | "Emergency";
  total: number;
  on_time: number;
  pct: number | null;
  target_minutes: number | null;
  median_minutes: number | null;
}

export interface TurnaroundLateOut {
  service: "Lab" | "Imaging";
  /** The lab test (lab_requisition_item_id) or the imaging order */
  item_id: number;
  /** The requisition or order number */
  reference: string;
  item_name: string;
  turnaround_class: "Routine" | "Emergency";
  patient_id: number;
  patient_name: string;
  mrn: string;
  started_at: string;
  due_at: string | null;
  /** Null: still open */
  done_at: string | null;
  minutes_taken: number | null;
  target_minutes: number | null;
  delay_reason: string | null;
  partner_name: string | null;
}

