/** Turnaround of lab results or imaging reports, with the MSDS score — GET /api/v1/diagnostics/turnaround (who may call: holders of diagnostics.quality.view). */
export function turnaroundReport(query: { service: "Lab" | "Imaging"; date_from: string; date_to: string }): Promise<TurnaroundOut> {
  return api<TurnaroundOut>("GET", withQuery(`/diagnostics/turnaround`, query), undefined);
}

